package uk.ac.ravensbourne.casevault.domain;
import jakarta.persistence.*; import java.util.*;
/** Metadata only; uploaded content is ciphertext outside the web root (CWE-434). */
@Entity @Table(name="evidence_files") public class EvidenceFile { @Id private UUID id; @ManyToOne @JoinColumn(name="case_id") private CaseRecord caseRecord; @ManyToOne @JoinColumn(name="organisation_id") private Organisation organisation; @Column(name="original_name_sanitised") private String name; @Column(name="stored_name") private UUID storedName; @Column(name="detected_mime") private String mime; @Column(name="size_bytes") private long size; @Column(columnDefinition="char(64)") private String sha256; private boolean encrypted; @ManyToOne @JoinColumn(name="uploaded_by") private UserAccount uploadedBy; protected EvidenceFile(){} public EvidenceFile(UUID id,CaseRecord c,String n,UUID stored,String m,long s,String hash,UserAccount u){this.id=id;caseRecord=c;organisation=c.getOrganisation();name=n;storedName=stored;mime=m;size=s;sha256=hash;encrypted=true;uploadedBy=u;} public UUID getId(){return id;} public CaseRecord getCaseRecord(){return caseRecord;} public String getName(){return name;} public UUID getStoredName(){return storedName;} public String getSha256(){return sha256;} }
